content='''def transform(grid):
    h, w = len(grid), len(grid[0])
    filled = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    placements = []
    corners = ((0, 0), (0, 1), (1, 0), (1, 1))
    color_for_missing = (2, 4, 3, 5)
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= filled:
                placements.append((box, 1))
            for i, (dr, dc) in enumerate(corners):
                shape = box - {(r + dr, c + dc)}
                if shape <= filled:
                    placements.append((shape, color_for_missing[i]))
    by_cell = {cell: [] for cell in filled}
    for shape, color in placements:
        for cell in shape:
            by_cell[cell].append((shape, color))
    answer = [[0] * w for _ in range(h)]
    def tile(left):
        if not left:
            return True
        cell = min(left)
        for shape, color in by_cell[cell]:
            if shape <= left:
                for r, c in shape:
                    answer[r][c] = color
                if tile(left - shape):
                    return True
                for r, c in shape:
                    answer[r][c] = 0
        return False
    if not tile(filled):
        raise ValueError("No valid square/L-triomino tiling")
    return answer
'''
